[4521] = { en = "Wild Guardians", tier = 4,
  t = "Wilde bewakers",
  d = "Winterspring ligt net voorbij Timbermaw, ten noordoosten van Felwood. Ben je daar al eens geweest?$B$BIk heb gehoord dat het gebied vol zit met wezens die wildkin heten. Van deze beesten is bekend dat ze geheimen bewaken: geheimen van de nachtelfen.$B$BWe moeten uitzoeken wat er misschien verborgen ligt in Winterspring.$B$BIk heb gehoord dat je de ragged owlbeasts net ten zuiden van de weg kunt vinden. Er zijn ook andere, raging owlbeasts genoemd, die je in het midden van Winterspring kunt vinden. Ruim ze op en krijg zo toegang tot het land.",
  o = "Trull Failbane in Felwood wil dat je 15 Raging Owlbeasts en 15 Ragged Owlbeasts doodt.",
  p = "Kom terug naar mij als je de taak hebt volbracht die ik je gaf.",
  c = "Dit is uitstekend nieuws, $N. Nu deze beesten uit de weg zijn, kunnen we verder Winterspring in trekken. Ben je klaar voor meer?",
  g = { {"bewakers", "guardians (bewaker)"}, {"ten noordoosten van", "northeast of"}, {"vol zit met", "is full of (vol zitten met)"}, {"bewaken", "to guard"}, {"nachtelfen", "night elves (nachtelf)"}, {"uitzoeken", "to find out"}, {"verborgen", "hidden"}, {"ruim ... op", "clear out (opruimen)"}, {"toegang", "access"}, {"volbracht", "completed (volbrengen)"}, {"uit de weg", "out of the way"} },
},

[4741] = { en = "Wild Guardians", tier = 4,
  t = "Wilde bewakers",
  d = "In de noordelijke delen van Winterspring worden de wildkin nog woester. We moeten daar doorgaan met onze maatregelen.$B$BJaag op de moontouched owlbeasts in Winterspring en verken het gebied waar ze leven.$B$BDit is gevaarlijk terrein, maar ik weet dat je de uitdaging aankunt. Kom terug naar mij als je 13 van de wildkin hebt gedood.",
  o = "Trull Failbane in Felwood wil dat je jaagt op 13 Moontouched Owlbeasts.",
  p = "Zeg me niet dat je te bang bent! Op weg!",
  c = "Ik voel dat je plezier hebt in je werk. En ik geloof dat we iets op het spoor zijn.",
  g = { {"noordelijke", "northern (noordelijk)"}, {"woester", "fiercer (woest)"}, {"maatregelen", "measures (maatregel)"}, {"jaag op", "hunt (jagen op)"}, {"verken", "explore (verkennen)"}, {"terrein", "ground, terrain"}, {"uitdaging", "challenge"}, {"aankunt", "can handle (aankunnen)"}, {"op het spoor zijn", "to be onto something"} },
},

[4721] = { en = "Wild Guardians", tier = 4,
  t = "Wilde bewakers",
  d = "Boodschappers zijn teruggekomen uit Winterspring. Ze melden dat er in het zuiden van Winterspring een reeks kleine grotten is. Rond die grotten lijken wildkin te leven. Als ze daar iets waardevols bewaken, dan vinden we het volgens mij op deze plek.$B$BDeze wezens zullen een grotere uitdaging zijn dan de vorige soorten, $N. Ze lijken gek geworden doordat ze blootstaan aan precies datgene wat ze proberen te beschermen.",
  o = "Trull Failbane in Felwood wil dat je jaagt op 10 Berserk Owlbeasts in Winterspring.",
  p = "Je kent je bevelen, $N.",
  c = "Voor hard werken heb ik veel respect, $N. Nu kunnen we verder met onze plannen voor Winterspring.",
  g = { {"boodschappers", "runners, messengers (boodschapper)"}, {"melden", "report"}, {"reeks", "series"}, {"grotten", "caves (grot)"}, {"waardevols", "valuable (waardevol)"}, {"soorten", "kinds, types (soort)"}, {"blootstaan aan", "to be exposed to"}, {"datgene wat", "that which"}, {"bevelen", "orders (bevel)"} },
},

})

